"""异步任务管理 — 后台执行战斗任务并管理状态。"""

from __future__ import annotations

import asyncio
import threading
import uuid
from dataclasses import dataclass, field, replace
from datetime import UTC, datetime
from enum import Enum
from typing import TYPE_CHECKING, Any

from autowsgr.infra.exceptions import get_graded_error_info
from autowsgr.infra.logger import get_logger
from autowsgr.server.device_lease import (
    DeviceOperationLease,
    DeviceOperationToken,
    device_operation_lease,
)
from autowsgr.server.ws_manager import task_ws_manager


if TYPE_CHECKING:
    from collections.abc import Callable, Coroutine
    from concurrent.futures import Future


_log = get_logger('server.task')


class TaskStatus(Enum):
    """任务状态。"""

    IDLE = 'idle'
    RUNNING = 'running'
    COMPLETED = 'completed'
    FAILED = 'failed'
    STOPPED = 'stopped'


@dataclass(frozen=True)
class TaskOutcome:
    """任务执行器的最终结果。

    执行器应当把每轮结果完整返回，并显式表达任务整体是否成功。这样
    ``TaskManager`` 无须根据“executor 是否抛异常”猜测业务结果。
    """

    results: list[dict[str, Any]]
    success: bool
    error: str | None = None
    stop_reason: str | None = None

    @classmethod
    def from_results(
        cls,
        results: list[dict[str, Any]],
        error: str | None = None,
        stop_reason: str | None = None,
    ) -> TaskOutcome:
        """根据逐轮结果构建任务结果，优先保留显式任务级错误。"""
        if error is not None:
            return cls(
                results=results,
                success=False,
                error=error,
                stop_reason=stop_reason,
            )

        failed_results = [result for result in results if not result.get('success', False)]
        if failed_results:
            error = next(
                (str(result['error']) for result in failed_results if result.get('error')),
                '一个或多个任务轮次失败',
            )
            return cls(
                results=results,
                success=False,
                error=error,
                stop_reason=stop_reason,
            )
        if not results:
            return cls(
                results=[],
                success=False,
                error='任务未执行任何轮次',
                stop_reason=stop_reason,
            )
        return cls(results=results, success=True, stop_reason=stop_reason)


@dataclass(frozen=True)
class TaskInfo:
    """任务信息的不可变快照（5.7）。

    ``TaskManager`` 每次状态变更都用 :func:`dataclasses.replace` 生成新实例，
    再在锁内替换 ``_current_task`` 引用；引用赋值本身是原子的，读方拿到的
    任何实例都是完整快照，不会读到「轮次已加、结果尚未写入」这类半截数据。

    ``results`` 用元组保存，写入时整体替换，读方不会看到正在追加的列表。
    唯一保留的活字段是 ``stop_requested``：它由共享的 ``threading.Event``
    承载，是给执行线程的协作式控制信号，必须实时可见，不属于状态快照。
    """

    task_id: str
    task_type: str
    status: TaskStatus = TaskStatus.IDLE
    created_at: str = field(default_factory=lambda: datetime.now(UTC).isoformat())
    started_at: str | None = None
    finished_at: str | None = None

    # 进度
    current_round: int = 0
    total_rounds: int = 0
    current_node: str | None = None

    # 结果
    results: tuple[dict[str, Any], ...] = ()
    error: str | None = None
    # 4.3 错误分级：供前端区分「可恢复 / 需人工 / 设备故障」
    error_code: str | None = None
    error_type: str | None = None
    # 5.11：后端统一轮次原语产出的停止原因，前端只读不重算。
    stop_reason: str | None = None

    # 控制：与 manager 共享的停止信号；不参与 repr/比较，replace() 时原样保留
    _stop_event: threading.Event = field(
        default_factory=threading.Event,
        repr=False,
        compare=False,
    )

    @property
    def stop_requested(self) -> bool:
        """任务是否已被请求停止（实时控制信号，不属于快照数据）。"""
        return self._stop_event.is_set()

    @property
    def progress(self) -> dict[str, Any]:
        """返回进度信息。"""
        return {
            'current': self.current_round,
            'total': self.total_rounds,
            'node': self.current_node,
        }

    @property
    def result_summary(self) -> dict[str, Any]:
        """返回结果摘要。"""
        return {
            'total_runs': self.total_rounds,
            'success_runs': sum(1 for r in self.results if r.get('success', False)),
            'details': list(self.results),
            'error': self.error,
            'error_code': self.error_code,
            'error_type': self.error_type,
            'stop_reason': self.stop_reason,
        }


class TaskManager:
    """任务管理器。

    管理任务的创建、执行、状态查询和取消。
    所有战斗操作在后台线程执行，避免阻塞事件循环。
    """

    def __init__(self, device_lease: DeviceOperationLease | None = None) -> None:
        self._current_task: TaskInfo | None = None
        self._executor_thread: threading.Thread | None = None
        self._stop_event = threading.Event()
        # RLock：start_task/stop_task 会在持锁状态下调用 is_running（同样加锁），
        # 且 5.2 的「释放租约 + 写终态」事务需要对外表现为一个原子步骤。
        self._lock = threading.RLock()
        self._loop: asyncio.AbstractEventLoop | None = None
        self._device_lease = device_lease or device_operation_lease

    @property
    def current_task(self) -> TaskInfo | None:
        """当前任务。"""
        return self._current_task

    @property
    def is_running(self) -> bool:
        """是否有任务正在运行。

        加锁读取，避免撞上「租约已释放、终态尚未写入」的过渡瞬间：任务
        准入若在该窗口看到 RUNNING，会对刚结束的任务误报「已有任务正在
        运行」（5.2 的另一个 409 来源）。
        """
        with self._lock:
            return (
                self._current_task is not None
                and self._current_task.status == TaskStatus.RUNNING
            )

    @property
    def stop_event(self) -> threading.Event:
        """任务执行使用的协作式停止信号。"""
        return self._stop_event

    def set_loop(self, loop: asyncio.AbstractEventLoop) -> None:
        """设置事件循环引用，用于从线程中调用 async 函数。"""
        self._loop = loop

    def _submit_to_loop(
        self,
        factory: Callable[[], Coroutine[Any, Any, None]],
        *,
        label: str,
    ) -> None:
        """把协程投递到 GUI 事件循环，循环已关闭时静默丢弃（5.8）。

        退出瞬间事件循环可能已经关闭，``run_coroutine_threadsafe`` 会抛
        ``RuntimeError``。这段代码跑在任务工作线程里，异常一旦逃出去，调用
        方（执行器/`_run_in_thread`）就会把已经成功收口的任务重新判成失败，
        因此这里只记 debug 并返回。
        """
        loop = self._loop
        if loop is None or loop.is_closed():
            return

        coro = factory()
        try:
            future = asyncio.run_coroutine_threadsafe(coro, loop)
        except RuntimeError:
            # 未投递的协程必须显式关闭，否则 GC 时报 "coroutine was never awaited"。
            coro.close()
            _log.debug('[Task] 事件循环已关闭，丢弃 {} 推送', label)
            return
        future.add_done_callback(self._consume_future_exception)

    @staticmethod
    def _consume_future_exception(future: Future[Any]) -> None:
        """吞掉后台推送的异常，避免退出瞬间污染任务结果（5.8）。"""
        try:
            error = future.exception()
        except Exception:  # 已取消 / 已关闭
            return
        if error is not None:
            _log.debug('[Task] WS 推送失败（已忽略）: {}', error)

    def start_task(
        self,
        task_type: str,
        total_rounds: int,
        executor: Callable[[TaskInfo], TaskOutcome],
    ) -> str:
        """启动新任务。

        Parameters
        ----------
        task_type:
            任务类型标识
        total_rounds:
            总轮次
        executor:
            执行函数，接收 TaskInfo，返回显式任务结果

        Returns
        -------
        str
            任务 ID
        """
        with self._lock:
            if self.is_running:
                raise RuntimeError('已有任务正在运行')

            task_id = f'task_{uuid.uuid4().hex[:8]}'
            lease_token = self._device_lease.acquire(f'task:{task_id}')
            self._stop_event.clear()
            # 5.7：executor 拿到的是启动瞬间的快照；它应通过 task_manager 的
            # update_progress/add_result/should_stop 观察后续变化，不要改这个对象。
            self._current_task = TaskInfo(
                task_id=task_id,
                task_type=task_type,
                status=TaskStatus.RUNNING,
                total_rounds=total_rounds,
                started_at=datetime.now(UTC).isoformat(),
                _stop_event=self._stop_event,
            )

            # 启动后台线程执行
            self._executor_thread = threading.Thread(
                target=self._run_in_thread,
                args=(executor, lease_token),
                daemon=True,
            )
            try:
                self._executor_thread.start()
            except Exception:
                self._current_task = None
                self._executor_thread = None
                self._device_lease.release(lease_token)
                raise

            _log.info('[Task] 启动任务: {} ({})', task_id, task_type)
            return task_id

    def _run_in_thread(
        self,
        executor: Callable[[TaskInfo], TaskOutcome],
        lease_token: DeviceOperationToken,
    ) -> None:
        """在后台线程中执行任务。

        终态写入必须排在租约释放之后（5.2）：一旦 ``status`` 离开
        ``RUNNING``，调度层就会立刻派下一个任务；若此时本任务的租约还没
        归还，新任务 ``acquire()`` 必然撞上 409。释放与写状态放在同一把
        任务锁里，状态查询因此只会看到「运行中 + 持有租约」或「终态 +
        空闲」两种一致组合。
        """
        assert self._current_task is not None
        task = self._current_task
        task_id = task.task_id

        status = TaskStatus.RUNNING
        error: str | None = None
        error_code: str | None = None
        error_type: str | None = None
        stop_reason: str | None = None
        final_results: tuple[dict[str, Any], ...] | None = None

        try:
            outcome = executor(task)
            final_results = tuple(dict(result) for result in outcome.results)
            stop_reason = outcome.stop_reason

            # 检查是否被请求停止（共享 Event，执行线程能实时看到）
            if self._stop_event.is_set():
                status = TaskStatus.STOPPED
                stop_reason = stop_reason or 'stopped'
            elif outcome.success:
                status = TaskStatus.COMPLETED
            else:
                status = TaskStatus.FAILED
                error = outcome.error
                # 执行器内部已收口的 4.3 分级错误：从最后一轮结果回填，
                # 让 /api/task/status 与 result_summary 也带 error_code。
                for result in reversed(final_results):
                    if result.get('error_code'):
                        error_code = str(result['error_code'])
                        error_type = (
                            str(result['error_type']) if result.get('error_type') else None
                        )
                        break

        except Exception as e:
            status = TaskStatus.FAILED
            error = str(e)
            graded = get_graded_error_info(e)
            if graded is not None:
                error_code = graded['error_code']
                error_type = graded['error_type']
                error = f"[{graded['error_type']}] {graded['error_hint']}: {e}"
                _log.error(
                    '[Task] 任务失败: {} - [{}] {} | {}',
                    task_id,
                    graded['error_type'],
                    graded['error_hint'],
                    e,
                )
            else:
                _log.error('[Task] 任务失败: {} - {}', task_id, e)

        finally:
            # BaseException（如 SystemExit）也要留下终态，不能永远 RUNNING。
            if status is TaskStatus.RUNNING:
                status = TaskStatus.FAILED
                error = error or '任务线程异常终止'

            # 5.2：先归还租约，再公开终态。两件事同锁，查询接口不会
            # 观察到「status 已终态 / 设备仍被占用」的矛盾窗口。
            # 5.7：在最新快照上 replace，进度/结果不会回退到启动瞬间。
            with self._lock:
                self._device_lease.release(lease_token)
                current = self._current_task
                assert current is not None
                changes: dict[str, Any] = {
                    'status': status,
                    'error': error,
                    'stop_reason': stop_reason,
                    'finished_at': datetime.now(UTC).isoformat(),
                }
                if status is TaskStatus.FAILED:
                    changes['error_code'] = error_code
                    changes['error_type'] = error_type
                if final_results is not None:
                    changes['results'] = final_results
                task = replace(current, **changes)
                self._current_task = task

            _log.info('[Task] 任务完成: {} ({})', task.task_id, task.status.value)

            # 5.8：关窗瞬间事件循环可能已关闭，推送失败不得影响任务终态。
            self._submit_to_loop(
                lambda: self._notify_completion(task),
                label='task_completed',
            )

    async def _notify_completion(self, task: TaskInfo) -> None:
        """发送任务完成通知。"""
        success = task.status == TaskStatus.COMPLETED
        result = (
            task.result_summary
            if task.status in (TaskStatus.COMPLETED, TaskStatus.FAILED, TaskStatus.STOPPED)
            else None
        )
        await task_ws_manager.send_task_completed(
            task_id=task.task_id,
            success=success,
            result=result,
            error=task.error,
        )

    def stop_task(self) -> bool:
        """请求停止当前任务。"""
        with self._lock:
            if not self.is_running or self._current_task is None:
                return False

            # stop_requested 是共享 Event 的实时视图（5.7）：置位即可，不必
            # 替换快照，执行线程手里那份 TaskInfo 也能立刻看到。
            self._stop_event.set()
            _log.info('[Task] 请求停止任务: {}', self._current_task.task_id)
            return True

    def wait_for_completion(self, timeout: float | None = None) -> bool:
        """等待当前 worker 实际退出。

        ``stop_task()`` 只发出协作式停止信号。生命周期调用方必须使用本方法
        确认 worker 已结束后，才能释放或替换其持有的 ``GameContext``。
        """
        thread = self._executor_thread
        if thread is None:
            return True
        if thread is threading.current_thread():
            return False
        thread.join(timeout=timeout)
        return not thread.is_alive()

    def update_progress(
        self,
        current_round: int | None = None,
        current_node: str | None = None,
    ) -> None:
        """更新任务进度 (从执行线程调用)。

        5.7：一次 ``replace`` 同时发布 ``current_round`` / ``current_node``，
        读方不会看到「轮次已更新、节点还是上一轮」的中间态。
        """
        changes: dict[str, Any] = {}
        if current_round is not None:
            changes['current_round'] = current_round
        if current_node is not None:
            changes['current_node'] = current_node

        with self._lock:
            task = self._current_task
            if task is None:
                return
            if changes:
                task = replace(task, **changes)
                self._current_task = task
            task_id = task.task_id
            progress = task.progress

        # 通过事件循环发送 WebSocket 更新；5.8：循环已关闭时静默丢弃。
        self._submit_to_loop(
            lambda: task_ws_manager.send_task_update(
                task_id=task_id,
                status='running',
                progress=progress,
            ),
            label='task_update',
        )

    def publish_loot_update(self, loot_count: int, ship_count: int) -> None:
        """从战斗线程发布一次掉落事件（5.9）。

        ``GameContext`` 的掉落计数在 worker 线程同步更新；这里复用 5.8 的
        线程安全投递入口，把结构化事件送到 ``/ws/task``。前端据此更新停止
        条件，不再依赖会被日志等级过滤掉的控制台文本。
        """
        self._submit_to_loop(
            lambda: task_ws_manager.send_loot_update(
                loot_count=loot_count,
                ship_count=ship_count,
            ),
            label='loot_update',
        )

    def publish_ui_state(self, state: dict[str, Any]) -> None:
        """从任务线程发布一次 UI 状态快照（4.5）。

        ``GameContext`` 在识别页面、切换子状态、推进战斗阶段时调用注入的
        sink；这里复用 5.8 的线程安全投递入口，把事件送到 ``/ws/task``。
        去重与频率控制在 ``GameContext.publish_ui_state`` 内完成，本方法只
        负责跨线程搬运，不再二次判断（任务启动的 ``force`` 基线必须能穿过）。
        """
        payload = {
            'page': state.get('page'),
            'stack': list(state.get('stack') or ()),
            'phase': state.get('phase'),
            'substate': state.get('substate'),
        }
        self._submit_to_loop(
            lambda: task_ws_manager.send_ui_state_update(**payload),
            label='ui_state_update',
        )

    def add_result(self, result: dict[str, Any]) -> None:
        """添加一轮结果 (从执行线程调用)。

        5.7：复制出新的元组再整体替换，读方永远看不到半追加的列表。
        """
        with self._lock:
            task = self._current_task
            if task is None:
                return
            # 浅拷贝：调用方之后若复用/修改 dict，不会污染已发布的快照。
            self._current_task = replace(task, results=(*task.results, dict(result)))

    def should_stop(self) -> bool:
        """检查是否应该停止 (从执行线程调用)。"""
        with self._lock:
            if self._current_task is None:
                return True
            return self._current_task.stop_requested

    def get_status(self) -> dict[str, Any]:
        """获取当前任务状态。

        与 ``_run_in_thread`` 的终态写入共用任务锁，保证「释放租约 + 写
        终态」对外是一个原子快照（5.2）。
        """
        with self._lock:
            task = self._current_task
            if task is None:
                return {
                    'task_id': None,
                    'status': TaskStatus.IDLE.value,
                    'progress': None,
                    'result': None,
                    'error': None,
                    'error_code': None,
                    'error_type': None,
                }

            result = None
            if task.status in (TaskStatus.COMPLETED, TaskStatus.FAILED, TaskStatus.STOPPED):
                result = task.result_summary

            return {
                'task_id': task.task_id,
                'status': task.status.value,
                'progress': task.progress if task.status == TaskStatus.RUNNING else None,
                'result': result,
                'error': task.error,
                'error_code': task.error_code,
                'error_type': task.error_type,
            }

    def get_device_lease(self) -> dict[str, str] | None:
        """安全读取设备租约快照。

        租约本身由 ``DeviceOperationLease`` 的锁保护，任务状态与租约可能由
        不同线程更新，因此这里只读取租约自己的加锁快照，不裸读任何任务字段。
        """
        return self._device_lease.snapshot()


# 全局单例
task_manager = TaskManager()
